def brands_build(outdir, write_page, models):
    """Брендовые хабы под топ-спрос Wordstat: /brands/{slug}.html"""
    from build import slug as _slug
    from catalog import shop_card_html as _card, PIDX as _pidx
    import html
    for bslug, brand, demand, line, title, desc, intro, intro2, pains_line, art_links, sku_ids, faqs in BRAND_HUBS:
        bmodels = [m for m in models if m['brand'].strip() == brand]
        rows = ''.join(
            '<tr><td><a href="/models/' + _slug(m['brand']) + '-' + _slug(m['model']) + '.html">' + html.escape(m['brand'] + ' ' + m['model']) + '</a></td>'
            '<td>' + html.escape(str(m.get('type') or '—')) + '</td>'
            '<td>' + html.escape(str(m.get('ac') or '—')) + ' / ' + html.escape(str(m.get('dc') or '—')) + '</td>'
            '<td>' + html.escape(str(m.get('freq') or '—')) + '</td></tr>' for m in bmodels)
        cards = ''.join(_card(_pidx[i]) for i in sku_ids)
        arts = ' · '.join('<a href="/blog/' + a + '.html">' + dict((sl, t) for sl, t, d in BLOG_ARTICLES).get(a, a) + '</a>' for a in art_links)
        faq_html_b = ''.join('<div class="faq-q"><b>' + q + '</b><p>' + a2 + '</p></div>' for q, a2 in faqs)
        body = ('<h1>' + html.escape(title) + '</h1>'
          '<p class="lede">' + html.escape(intro) + '</p>'
          '<p>' + html.escape(intro2) + '</p>'
          '<p class="note">Типичные боли линейки: ' + html.escape(pains_line) + '</p>'
          '<h2>Модели ' + html.escape(brand) + ' в России: разъёмы и частота ввоза</h2>'
          '<div class="tw"><table><tr><th>Модель</th><th>Тип</th><th>AC / DC</th><th>Ввоз</th></tr>' + rows + '</table></div>'
          '<h2>Что докупить</h2><div class="pc-grid">' + cards + '</div>'
          '<h2>Гайды по моделям</h2><p>' + arts + '</p>'
          '<h2>Частые вопросы</h2>' + faq_html_b
          + _cta('Подбор комплекта под ' + brand))
        write_page(os.path.join(outdir, 'brands', bslug + '.html'),
                   title + ' | Запас хода', desc, body, '/brands/' + bslug + '.html',
                   crumbs=[('', brand)], extra_ld=faq_ld(faqs))

# --- Открытые данные: /open-data/ ---
def open_data_build(outdir, write_page):
    """Страница открытых данных по зарядным станциям: описание и примеры использования."""
    body = ('<h1>Открытые данные: зарядные станции России</h1>'
      '<p class="lede">Мы отдаём базу зарядных станций сайта как открытый файл: ' + '<a href="/charging/stations.json">/charging/stations.json</a>' + '. Данные собраны из OpenStreetMap, файл — статический JSON, обновляется регулярно. Берите для ботов, чатов, приложений и исследований.</p>'
      '<h2>Формат</h2>'
      '<div class="tw"><table><tr><th>Поле</th><th>Что содержит</th></tr>'
      '<tr><td>updated</td><td>дата выгрузки (YYYY-MM-DD)</td></tr>'
      '<tr><td>stations[].lat, lon</td><td>координаты WGS-84</td></tr>'
      '<tr><td>stations[].n</td><td>название точки</td></tr>'
      '<tr><td>stations[].c</td><td>число портов (если указано в OSM)</td></tr>'
      '<tr><td>stations[].a</td><td>адрес/комментарий (если есть)</td></tr>'
      '<tr><td>stations[].s</td><td>список разъёмов: type2, ccs2, chademo, gbt, yazaki, schuko и др.</td></tr></table></div>'
      '<h2>Пример</h2>'
      '<div class="lcard"><code>curl -s https://zapashoda-ev.ru/charging/stations.json | head -c 400</code>'
      '<p class="note">Файл без ограничений на запросы (статический CDN GitHub Pages). Точка обновления данных — выгрузка из OSM.</p></div>'
      '<h2>Условия использования</h2>'
      '<p>Данные производны от OpenStreetMap — условия ODbL: указывайте «© OpenStreetMap contributors» при использовании. Ссылка на сайт приветствуется, но не обязательна.</p>'
      '<h2>Что строить на этих данных</h2>'
      '<ul><li>боты и чаты «где зарядиться»;</li><li>карты для региональных сообществ;</li><li>аналитика плотности сети по регионам;</li><li>интеграция в приложения и навигацию.</li></ul>'
      '<p>Если построили что-то полезное — напишите в <a href="https://t.me/zapashoda_ev" target="_blank" rel="noopener">Telegram</a>: расскажем о вашем проекте в новостях сайта.</p>')
    desc = 'Открытая база зарядных станций России (stations.json) из OpenStreetMap: формат, примеры использования, условия ODbL. Для ботов, карт и исследований.'
    write_page(os.path.join(outdir, 'open-data', 'index.html'),
               'Открытые данные: зарядные станции России | Запас хода', desc, body,
               '/open-data/index.html', crumbs=[('', 'Открытые данные')],
               extra_ld='<script type="application/ld+json">' + art_ld('Открытые данные: зарядные станции', desc, '/open-data/index.html') + '</script>')
